{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Linezolid, the closest oxazolidinone analogue (Morgan 0.4507), has essentially complete absolute oral bioavailability (~100%) in patients, directly supporting high F for the query's shared oxazolidinone-acylaminomethyl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "YH4808, a thiomorpholine-containing oxazolidinone analogue (Morgan 0.4054), had low absolute oral bioavailability of 10.1%, providing a threshold-relevant counterexample; however, its thiomorpholine, fluoro, and acetyl substituents differ from the query's morpholinone and thiophene amide, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Delpazolid (LCB01-0371), an oxazolidinone with a 5-substituent and heteroaryl piperazine, showed 99.75% absolute oral bioavailability in healthy volunteers, supporting high F for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Contezolid, a fluorinated oxazolidinone with an isoxazole amide side chain, had absolute bioavailability of 64%, still well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Cadazolid, a large polar oxazolidinone-quinolone hybrid, had very low oral bioavailability, but it is intentionally gut-restricted and structurally dissimilar (Morgan 0.233), so it is a weak contradictory signal.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high oral bioavailability (F >= 20%). The closest and most transferable analogue, linezolid, has ~100% absolute oral bioavailability, and other oxazolidinones (delpazolid, contezolid) also exceed the threshold. The only low-F analogue, YH4808, is less similar and differs in key substituents (thiomorpholine vs morpholinone; acetyl vs thiophene amide), reducing its weight. The physicochemical prior is also favorable.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "Mechanism of YH4808's low bioavailability is not established, so its relevance to the query's morpholinone/thiophene amide structure is uncertain.",
    "Metabolic stability of the thiophene amide and potential transporter/efflux effects are unknown.",
    "No solubility or dissolution data specific to the query are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

